ALTER TABLE "growth_action_events" ADD CONSTRAINT "growth_action_events_transition_check" CHECK ("growth_action_events"."event_type" = 'created' OR ("growth_action_events"."from_status" = 'approved' AND "growth_action_events"."to_status" IN ('ready','implemented','cancelled')) OR ("growth_action_events"."from_status" = 'ready' AND "growth_action_events"."to_status" IN ('in_progress','implemented','cancelled')) OR ("growth_action_events"."from_status" = 'in_progress' AND "growth_action_events"."to_status" IN ('blocked','implemented','cancelled')) OR ("growth_action_events"."from_status" = 'blocked' AND "growth_action_events"."to_status" IN ('in_progress','implemented','cancelled')) OR ("growth_action_events"."from_status" = 'implemented' AND "growth_action_events"."to_status" = 'measuring') OR ("growth_action_events"."from_status" = 'measuring' AND "growth_action_events"."to_status" = 'evaluated'));--> statement-breakpoint
ALTER TABLE "growth_actions" ADD CONSTRAINT "growth_actions_milestones_check" CHECK ("growth_actions"."approved_at" IS NOT NULL AND (("growth_actions"."status" = 'approved' AND "growth_actions"."started_at" IS NULL AND "growth_actions"."implemented_at" IS NULL AND "growth_actions"."evaluated_at" IS NULL AND "growth_actions"."cancelled_at" IS NULL) OR ("growth_actions"."status" = 'ready' AND "growth_actions"."started_at" IS NULL AND "growth_actions"."implemented_at" IS NULL AND "growth_actions"."evaluated_at" IS NULL AND "growth_actions"."cancelled_at" IS NULL) OR ("growth_actions"."status" IN ('in_progress','blocked') AND "growth_actions"."started_at" IS NOT NULL AND "growth_actions"."implemented_at" IS NULL AND "growth_actions"."evaluated_at" IS NULL AND "growth_actions"."cancelled_at" IS NULL) OR ("growth_actions"."status" IN ('implemented','measuring') AND "growth_actions"."implemented_at" IS NOT NULL AND "growth_actions"."evaluated_at" IS NULL AND "growth_actions"."cancelled_at" IS NULL) OR ("growth_actions"."status" = 'evaluated' AND "growth_actions"."implemented_at" IS NOT NULL AND "growth_actions"."evaluated_at" IS NOT NULL AND "growth_actions"."cancelled_at" IS NULL) OR ("growth_actions"."status" = 'cancelled' AND "growth_actions"."implemented_at" IS NULL AND "growth_actions"."evaluated_at" IS NULL AND "growth_actions"."cancelled_at" IS NOT NULL)));